'use strict';
const $=id=>document.getElementById(id);let source=null,name='',result=null,previewUrl=null,revision=0;
function message(s,bad=false){$('status').textContent=s;$('status').classList.toggle('error',bad);}
function bytes(n){return n>=1048576?(n/1048576).toFixed(2)+' MiB':(n/1024).toFixed(1)+' KiB';}
function clear(){revision++;source=null;result=null;$('download').disabled=true;$('loaded').hidden=true;$('drop').hidden=false;$('audio').pause();$('audio').hidden=true;$('audio').removeAttribute('src');if(previewUrl){URL.revokeObjectURL(previewUrl);previewUrl=null;}for(const id of ['duration','size','memory'])$(id).textContent='—';}
async function load(file){clear();const current=revision;if(!file)return;message('Reading audio…');try{if(file.size>80*1024*1024)throw Error('This file exceeds 80 MiB. Choose a shorter audio clip.');const buffer=await file.arrayBuffer();if(current!==revision)return;const imported=await MDAudio.decode(buffer,file.name);if(current!==revision)return;source=imported;name=file.name.replace(/\.[^.]+$/,'');$('filename').textContent=file.name;$('source-info').textContent=`${source.kind} · ${source.rate.toLocaleString('en-US')} Hz${source.decoded?' decoded':` · ${source.bits}-bit${source.format===3?' float':''}`} · ${source.channels.length===1?'mono':'stereo'}`;$('channel').disabled=source.channels.length===1;$('drop').hidden=true;$('loaded').hidden=false;draw();await update();}catch(e){if(current===revision){clear();message(e.message,true);}}}
function draw(){const canvas=$('wave'),ctx=canvas.getContext('2d'),ratio=window.devicePixelRatio||1,w=canvas.clientWidth,h=100;canvas.width=w*ratio;canvas.height=h*ratio;ctx.scale(ratio,ratio);ctx.clearRect(0,0,w,h);ctx.strokeStyle='#bdc7ac';ctx.beginPath();ctx.moveTo(0,50);ctx.lineTo(w,50);ctx.stroke();const a=source.channels[0];ctx.strokeStyle='#576b43';ctx.lineWidth=1;for(let x=0;x<w;x++){let lo=1,hi=-1;const first=Math.floor(x*a.length/w),last=Math.max(first+1,Math.floor((x+1)*a.length/w));for(let i=first;i<last&&i<a.length;i++){lo=Math.min(lo,a[i]);hi=Math.max(hi,a[i]);}ctx.beginPath();ctx.moveTo(x,50-hi*42);ctx.lineTo(x,50-lo*42);ctx.stroke();}}
async function update(){if(!source)return;const current=++revision,w=source;result=null;$('download').disabled=true;$('audio').pause();$('audio').hidden=true;message('Converting…');await new Promise(r=>setTimeout(r,30));if(current!==revision)return;try{const rate=Number($('rate').value),a=MDSDS.resample(MDSDS.mono(w,$('channel').value),w.rate,rate);const syx=MDSDS.encode(a,rate);if(current!==revision)return;result=syx;$('duration').textContent=(a.length/rate).toFixed(2)+' s';$('size').textContent=bytes(syx.length);$('memory').textContent=bytes(a.length*2);if(previewUrl)URL.revokeObjectURL(previewUrl);previewUrl=URL.createObjectURL(new Blob([MDSDS.preview(a,rate)],{type:'audio/wav'}));$('audio').src=previewUrl;$('audio').hidden=false;$('download').disabled=false;message(w.clipped?'Ready. Out-of-range peaks were limited. Check the preview.':'Ready. Converted to mono, with no normalization.');}catch(e){if(current===revision){for(const id of ['duration','size','memory'])$(id).textContent='—';message(e.message,true);}}}
$('file').addEventListener('change',e=>load(e.target.files[0]));$('replace').onclick=()=>{$('file').value='';$('file').click();};for(const id of ['rate','channel'])$(id).onchange=update;
for(const event of ['dragenter','dragover'])$('drop').addEventListener(event,e=>{e.preventDefault();$('drop').classList.add('drag');});for(const event of ['dragleave','drop'])$('drop').addEventListener(event,e=>{e.preventDefault();$('drop').classList.remove('drag');});$('drop').addEventListener('drop',e=>load(e.dataTransfer.files[0]));
$('download').onclick=()=>{if(!result)return;const url=URL.createObjectURL(new Blob([result],{type:'application/octet-stream'})),a=document.createElement('a');a.href=url;a.download=name+'.syx';document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);};window.addEventListener('resize',()=>{if(source)draw();});
